<style scoped>
.grid-3 {
  --grid-gap: var(--gap);
  gap: var(--grid-gap);
}

.step {
  position: relative;
  margin-top: 2rem;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.step:not(:last-child)::after {
  content: '';
  position: absolute;
  top: 10%;
  right: calc(var(--grid-gap) / -2 - 24px);
  width: 48px;
  height: 48px;
  transform: translateY(-50%);
  background-repeat: no-repeat;
  background-size: contain;
  pointer-events: none;
  background-image: v-bind('arrowRightUrl');
  opacity: 0.9;
}

.step-title {
  font-size: var(--title-size);
  font-weight: 600;
  color: var(--text-primary);
  margin-top: 2rem;
  margin-bottom: 1rem;
  font-family: var(--font-family);
}

.step-description {
  color: var(--text-secondary);
  line-height: 1.6;
  font-size: var(--description-size);
  font-family: var(--font-family);
}

.card {
  text-align: center;
}

.card-title {
  background: linear-gradient(135deg, #fff 0%, #f0f0f0 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

@media (max-width: 768px) {
  .grid-3 {
    grid-template-columns: 1fr;
    --grid-gap: 4rem;
    gap: var(--grid-gap);
  }
  .step:not(:last-child)::after {
    top: auto;
    bottom: calc(var(--grid-gap) / -2 - 36px);
    left: 50%;
    right: auto;
    width: 48px;
    height: 48px;
    transform: translateX(-50%) rotate(90deg);
  }
}
</style>
